#include "room_strategy.hpp"
#include "room_json.hpp"
#include <iostream>
int main(){using namespace wot::room;std::string line;while(std::getline(std::cin,line)){try{auto request=parseJson(line);State state;state.round_id=1;state.phase="battle";state.server_tick=300;state.config.object["prebattle_seconds"]=number(10.);state.rules.object["capture_context"]=request.get("context");state.bot_orders=request.get("orders");state.bot_manifest=request.get("manifest");for(const auto&p:rows(request.get("players")))state.players[intField(p,"id")]=p;for(const auto&bot:rows(request.get("bots")))state.bots[intField(bot,"id")]=bot;for(const auto&group:std::array<std::pair<const char*,bool>,2>{{{"player_spotted",false},{"bot_spotted",true}}})for(const auto&v:request.get(group.first).resolved().object){auto&spotted=group.second?state.bot_spotted:state.player_spotted;for(const auto&target:rows(v.second))spotted[std::stoll(v.first)].emplace(rows(target)[0].resolved().text,rows(target)[1].integer);}Planner planner(state);auto output=array();for(const auto&command:rows(request.get("commands"))){state.pending_deliveries.clear();if(has(command,"tick"))state.server_tick=intField(command,"tick");if(has(command,"phase"))state.phase=command.get("phase").resolved().text;if(has(command,"context"))state.rules.object["capture_context"]=command.get("context");for(const auto&patch:command.get("players").resolved().object)for(const auto&v:patch.second.resolved().object)state.players[std::stoll(patch.first)].object[v.first]=v.second;for(const auto&patch:command.get("bots").resolved().object)for(const auto&v:patch.second.resolved().object)state.bots[std::stoll(patch.first)].object[v.first]=v.second;Outcome result;if(command.get("advance").truth())planner.advanceRadio();else if(has(command,"cancel")){std::set<std::int64_t>cancelled;for(const auto&v:rows(command.get("cancel")))cancelled.insert(v.integer);planner.cancelRadio(cancelled);}else if(has(command,"clear"))planner.clearRadio(command.get("clear").text);else result=planner.dispatchRadio({intField(command,"sender",1),false},command.get("message"));auto out=object();out.object["ack"]=result.replies.empty()?Value{}:result.replies.front();out.object["commands"]=state.team_commands;out.object["deliveries"]=array();for(const auto&v:state.pending_deliveries){auto row=array();row.array={integer(v.first),v.second};out.object["deliveries"].array.push_back(std::move(row));}out.object["players"]=array();for(const auto&p:state.players){auto row=object();row.object["id"]=integer(p.first);for(const auto*k:{"team_command_seq","team_command_ready_tick"})row.object[k]=integer(intField(p.second,k));row.object["team_command_refusal_sent"]=boolean(p.second.get("team_command_refusal_sent").truth());out.object["players"].array.push_back(std::move(row));}output.array.push_back(std::move(out));}std::cout<<writeJson(output)<<'\n';}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}}
